        const char4 sc1 = as_type<char4>(utmp[0]);
        const char4 sc2 = as_type<char4>(utmp[1]);

        const float dall = x[i].d;

        float sum = 0;
        for (int k = 0; k < 4; ++k) {
            sum += y[k+ 0] * (sc1[is+0] - 32) * (((q[k] >> 0) & 3) - (hm[k] & (m << 0) ? 0 : 4))
